/*
 * Procedural assets: everything the game shows and plays is generated by code at start-up
 * (Windows, Android, headless) instead of being stored, which keeps the builds tiny.
 * The PS1 build links the same generators into tools/gen_dump on the host and embeds the output.
 */
#ifndef GEN_H
#define GEN_H

#include "sfx_ids.h"

/* ---- sounds */
typedef struct { const signed char *data; int len, rate, loop; } SfxPcm;
extern SfxPcm sfx_pcm[SFX_COUNT];
typedef void (*GenSfxFn)(void *user, int id, const float *y, int n, int sr, int loop);
void gen_sfx_each(GenSfxFn fn, void *user);     /* every sound as floats -1..1 */
void gen_sfx(void);                             /* fills sfx_pcm (once) */

#endif
